#!/usr/bin/env python3

import csv
import json
from pathlib import Path

THERAPY_CATALOG_PATH = Path("/root/therapy_catalog.json")
BAG_SUPPLY_COST_PATH = Path("/root/bag_supply_cost.csv")
DELIVERY_PAYMENT_PATH = Path("/root/delivery_payment.csv")
PATIENT_OVERRIDES_PATH = Path("/root/patient_overrides.csv")

OUT_JSON_PATH = Path("/root/infusion_batch_analysis.json")
OUT_MD_PATH = Path("/root/infusion_batch_summary.md")


ASSUMPTIONS = {
    "deliveries_per_year_7_day": 52,
    "deliveries_per_year_14_day": 26,
    "days_per_delivery_7_day": 7,
    "days_per_delivery_14_day": 14,
    "switch_threshold_usd": 15000,
    "patient_override_rule": "highest approved revision per therapy_code",
}


def _read_csv(path: Path):
    with path.open("r", newline="") as f:
        return list(csv.DictReader(f))


def _coerce_int(value, default=None):
    try:
        return int(value)
    except Exception:
        return default


def _coerce_float(value, default=None):
    try:
        return float(value)
    except Exception:
        return default


def load_therapies(path: Path):
    """Load therapies from a JSON that may be a list or a nested catalog."""
    data = json.loads(path.read_text())

    # Instruction says: list of therapy objects.
    # Observed input is a nested catalog: {service_lines: [{..., therapies: [...]}, ...]}.
    if isinstance(data, list):
        therapies = data
    elif isinstance(data, dict):
        if "therapies" in data and isinstance(data["therapies"], list):
            therapies = data["therapies"]
        elif "service_lines" in data and isinstance(data["service_lines"], list):
            therapies = []
            for sl in data["service_lines"]:
                if isinstance(sl, dict) and isinstance(sl.get("therapies"), list):
                    therapies.extend(sl["therapies"])
        else:
            therapies = []
    else:
        therapies = []

    # Keep only include_in_review == True
    in_scope = [t for t in therapies if bool(t.get("include_in_review")) is True]
    return in_scope


def resolve_delivery_payments(in_scope_therapies, delivery_payment_rows):
    """Map therapy_code -> payment_per_delivery_per_patient_usd by label matching."""
    # Build label->therapy_code index for exact-match lookups.
    label_to_code = {}
    for t in in_scope_therapies:
        code = t.get("therapy_code")
        labels = []
        if t.get("therapy_name"):
            labels.append(t["therapy_name"])
        aliases = t.get("aliases") or []
        if isinstance(aliases, list):
            labels.extend([a for a in aliases if a])
        for lbl in labels:
            # If duplicates exist, keep the first mapping to stay deterministic.
            label_to_code.setdefault(lbl, code)

    payments_by_code = {}
    for row in delivery_payment_rows:
        label = row.get("therapy_label")
        if not label:
            continue
        code = label_to_code.get(label)
        if not code:
            # Ignore rows that don't match any in-scope therapy.
            continue
        payment = _coerce_float(row.get("payment_per_delivery_per_patient_usd"), default=None)
        if payment is None:
            continue
        payments_by_code[code] = payment

    return payments_by_code


def resolve_active_patients(in_scope_codes, patient_override_rows):
    """Map therapy_code -> active_patients using highest approved revision."""
    if not patient_override_rows:
        return {}

    # Identify the patient count column.
    fieldnames = list(patient_override_rows[0].keys())
    if "patient_count" in fieldnames:
        patient_col = "patient_count"
    elif "active_patients" in fieldnames:
        patient_col = "active_patients"
    else:
        # Best-effort fallback.
        candidates = [c for c in fieldnames if "patient" in c.lower() and "count" in c.lower()]
        patient_col = candidates[0] if candidates else fieldnames[-1]

    best_by_code = {}

    for row in patient_override_rows:
        code = row.get("therapy_code")
        if not code or code not in in_scope_codes:
            continue
        if row.get("status") != "approved":
            continue

        rev = _coerce_int(row.get("revision"), default=None)
        if rev is None:
            continue

        patient_count = _coerce_int(row.get(patient_col), default=None)
        if patient_count is None:
            continue

        prev = best_by_code.get(code)
        if prev is None or rev > prev["revision"]:
            best_by_code[code] = {"revision": rev, "active_patients": patient_count}

    return {code: v["active_patients"] for code, v in best_by_code.items()}


def load_bag_supply_costs(rows):
    costs = {}
    for row in rows:
        bag_size = _coerce_int(row.get("bag_size_ml"), default=None)
        cost = _coerce_float(row.get("bag_supply_cost_usd"), default=None)
        if bag_size is None or cost is None:
            continue
        costs[bag_size] = cost
    return costs


def compute_currency(x):
    return round(float(x), 2)


def main():
    therapies = load_therapies(THERAPY_CATALOG_PATH)

    # Sort therapies by therapy_code ascending (required).
    therapies = sorted(therapies, key=lambda t: t.get("therapy_code") or "")

    bag_supply_rows = _read_csv(BAG_SUPPLY_COST_PATH)
    payment_rows = _read_csv(DELIVERY_PAYMENT_PATH)
    overrides_rows = _read_csv(PATIENT_OVERRIDES_PATH)

    bag_cost_by_size = load_bag_supply_costs(bag_supply_rows)

    in_scope_codes = {t.get("therapy_code") for t in therapies if t.get("therapy_code")}

    payment_by_code = resolve_delivery_payments(therapies, payment_rows)
    active_patients_by_code = resolve_active_patients(in_scope_codes, overrides_rows)

    def compute_for_model(days_per_delivery: int, deliveries_per_year: int, therapy):
        code = therapy["therapy_code"]
        active_patients = active_patients_by_code.get(code, 0)
        drug_cost_per_1000 = float(therapy["drug_cost_per_1000_mg_usd"])
        dose_per_day = float(therapy["dose_mg_per_day"])
        payment = float(payment_by_code.get(code, 0.0))

        bag_size = int(therapy["bag_size_ml"])
        bag_supply_cost = float(bag_cost_by_size.get(bag_size, 0.0))

        annual_drug_cost = (
            drug_cost_per_1000
            * active_patients
            * dose_per_day
            * days_per_delivery
            * deliveries_per_year
            / 1000.0
        )
        annual_supply_cost = bag_supply_cost * active_patients * deliveries_per_year
        annual_revenue = payment * active_patients * deliveries_per_year
        annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost

        return {
            "annual_drug_cost_usd": compute_currency(annual_drug_cost),
            "annual_supply_cost_usd": compute_currency(annual_supply_cost),
            "annual_revenue_usd": compute_currency(annual_revenue),
            "annual_margin_usd": compute_currency(annual_margin),
        }

    therapies_out = []

    for t in therapies:
        code = t.get("therapy_code")
        if not code:
            continue

        active_patients = int(active_patients_by_code.get(code, 0))
        bag_size = int(t.get("bag_size_ml"))
        bag_supply_cost = float(bag_cost_by_size.get(bag_size, 0.0))
        payment = float(payment_by_code.get(code, 0.0))

        model_7 = compute_for_model(
            days_per_delivery=ASSUMPTIONS["days_per_delivery_7_day"],
            deliveries_per_year=ASSUMPTIONS["deliveries_per_year_7_day"],
            therapy=t,
        )
        model_14 = compute_for_model(
            days_per_delivery=ASSUMPTIONS["days_per_delivery_14_day"],
            deliveries_per_year=ASSUMPTIONS["deliveries_per_year_14_day"],
            therapy=t,
        )

        margin_diff = compute_currency(model_14["annual_margin_usd"] - model_7["annual_margin_usd"])

        therapies_out.append(
            {
                "therapy_code": code,
                "therapy_name": t.get("therapy_name"),
                "active_patients": active_patients,
                "bag_size_ml": bag_size,
                "bag_supply_cost_usd": compute_currency(bag_supply_cost),
                "payment_per_delivery_per_patient_usd": compute_currency(payment),
                "drug_cost_per_1000_mg_usd": compute_currency(float(t.get("drug_cost_per_1000_mg_usd"))),
                "dose_mg_per_day": float(t.get("dose_mg_per_day")),
                "annual_drug_cost_7_day_usd": model_7["annual_drug_cost_usd"],
                "annual_supply_cost_7_day_usd": model_7["annual_supply_cost_usd"],
                "annual_revenue_7_day_usd": model_7["annual_revenue_usd"],
                "annual_margin_7_day_usd": model_7["annual_margin_usd"],
                "annual_drug_cost_14_day_usd": model_14["annual_drug_cost_usd"],
                "annual_supply_cost_14_day_usd": model_14["annual_supply_cost_usd"],
                "annual_revenue_14_day_usd": model_14["annual_revenue_usd"],
                "annual_margin_14_day_usd": model_14["annual_margin_usd"],
                "annual_margin_difference_14_minus_7_usd": margin_diff,
            }
        )

    # Totals (sum of per-therapy rounded margins; then round totals to 2 decimals).
    total_7 = compute_currency(sum(t["annual_margin_7_day_usd"] for t in therapies_out))
    total_14 = compute_currency(sum(t["annual_margin_14_day_usd"] for t in therapies_out))
    total_diff = compute_currency(sum(t["annual_margin_difference_14_minus_7_usd"] for t in therapies_out))
    abs_total_diff = compute_currency(abs(total_diff))

    threshold = ASSUMPTIONS["switch_threshold_usd"]
    decision = "move_to_14_day" if abs_total_diff < threshold else "keep_7_day"

    out = {
        "assumptions": ASSUMPTIONS,
        "therapies": therapies_out,
        "totals": {
            "total_annual_margin_7_day_usd": total_7,
            "total_annual_margin_14_day_usd": total_14,
            "total_annual_margin_difference_14_minus_7_usd": total_diff,
            "absolute_total_margin_difference_usd": abs_total_diff,
        },
        "recommendation": {
            "decision": decision,
            "justification": (
                f"Absolute total annual margin difference is ${abs_total_diff:.2f}, "
                f"compared to the switch threshold of ${threshold:.2f}."
            ),
        },
    }

    OUT_JSON_PATH.write_text(json.dumps(out, indent=2) + "\n")

    # 4–8 non-empty lines summary
    lines = [
        f"Total 7-day margin (USD): {total_7:.2f}",
        f"Total 14-day margin (USD): {total_14:.2f}",
        f"Absolute difference (USD): {abs_total_diff:.2f}",
        f"Final decision: {decision}",
    ]
    OUT_MD_PATH.write_text("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()

